// Interaction fixtures only. No microphone, ASR, model, target lookup or OS input.
const SOURCE='这次先保留完整的识别结果，异常结束时也不要清空。请在周五之前给我看一版原型，确认后再实施。';
const VOICE2='请保留完整的识别结果，异常结束时不要清空。周五前先看原型，确认后再实施。这轮先保留本地版本。';
const VOICE3='保留识别结果，异常时不要清空。周五前确认原型，再实施。本轮只保留本地版本，不自动输入。';
const LAST_PREVIEW='这次先保留完整的识别结果，异常结束时也不要清空。请在周五之前';
const RECOVERED='这次先保留完整的识别结果，异常结束时也不要清空。请在周五之前给我看一版原型';
const STORAGE='hyprvoice-review-v2';
const params=new URLSearchParams(location.search);
let theme=['compare','indigo','sage'].includes(params.get('theme'))?params.get('theme'):'indigo';
let active=['read','asr','edit','error','voice'].includes(params.get('state'))?params.get('state'):'read';
const sheet=params.get('view')==='sheet';
const specs={read:{name:'默认阅读',subtitle:'一份正文，随时检查与修改'},asr:{name:'识别校对',subtitle:'只标出不同片段，点击后原位选择'},edit:{name:'整段编辑',subtitle:'草稿独立保存，完成后再确认'},error:{name:'中断恢复',subtitle:'保留已识别内容，不自动输入'},voice:{name:'语音修改',subtitle:'要求、正文、版本分开保存'}};
const differences=[{before:'识别结果',alternate:'识别记录',offset:0},{before:'周五',alternate:'周四',offset:1}];
const states=Object.fromEntries(Object.keys(specs).map(id=>[id,{id,text:id==='error'?RECOVERED:id==='voice'?VOICE2:SOURCE,revision:1,target:true,targetOpen:false,notice:'',closed:false,mode:id==='asr'?'compare':'read',selected:[0,0],checked:[false,false],openDiff:id==='asr'?0:-1,editing:id==='edit',draft:id==='edit'?SOURCE:null,draftBase:1,manual:false,revised:id==='voice',errorKind:'device',recovery:'done',voicePhase:'ready',revisionFailed:false,replacementOpen:false,history:id==='voice'?[SOURCE,VOICE2]:[SOURCE],instruction:'把句子说得简洁些，补充“这轮先保留本地版本”。'}]));
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');for(const id of Object.keys(states)){if(saved[id])Object.assign(states[id],saved[id],{notice:'',closed:false});}}catch{}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(states));}catch{}}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function icon(name){return `<img src="icons/${name}.svg" alt="" aria-hidden="true">`;}
function btn(action,text,{cls='action',disabled=false,ic='',label='',tip='',extra=''}={}){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''} ${label?`aria-label="${esc(label)}"`:''} title="${esc(tip||label||text.replace(/<[^>]*>/g,''))}" ${extra}>${ic?icon(ic):''}${text}</button>`;}
function voiceContext(s){return s.id==='voice'||s.revised;}
function asrContext(s){return s.id==='asr'&&!s.manual&&!s.revised;}
function validText(s){return !!s.text.trim();}
function sourceText(s){let text=SOURCE;differences.forEach((d,i)=>{text=text.replace(d.before,s.selected[i]?d.alternate:d.before);});return text;}
function asrBody(s){let html=esc(SOURCE);differences.forEach((d,i)=>{const word=s.selected[i]?d.alternate:d.before;html=html.replace(esc(d.before),`<button class="asr-mark ${s.checked[i]?'resolved':''} ${s.openDiff===i?'active':''}" data-action="open-diff" data-diff="${i}" aria-expanded="${s.openDiff===i}" aria-label="检查识别差异：${word}">${esc(word)}</button>`);});return html;}
function candidate(s){if(s.openDiff<0||s.mode!=='compare'||s.manual)return '';const n=s.openDiff,d=differences[n],selected=s.selected[n];const words=selected?[d.alternate,d.before]:[d.before,d.alternate];const sources=selected?['实时识别','精修识别']:['精修识别','实时识别'];return `<aside class="candidate-popup" data-anchor="${n}" aria-label="${esc(d.before)}的识别候选"><div class="popup-heading"><span>音频识别差异 · ${n+1} / 2</span>${btn('close-diff','收起',{cls:'icon-button close-popup'})}</div>${btn('accept-current',`<span class="word">${esc(words[0])}</span><span class="source"><span class="selected-label">当前采用</span>${sources[0]} · 保留此项</span>`,{cls:'candidate-row current',label:`保留当前${words[0]}`})}<div class="candidate-divider"></div>${btn('choose',`<span class="word">${esc(words[1])}</span><span class="source">${sources[1]} · 点击采用</span>`,{cls:'candidate-row',label:`采用备选${words[1]}`})}<div class="popup-tip">共同文字不重复；这两项都来自音频识别。</div></aside>`;}
function revisionMarkup(s){if(s.history.length===2&&s.history[0]===SOURCE&&s.text===VOICE2)return `<span class="change-delete">这次先</span><span class="change-tag">删除</span><span class="change-replace">请</span>保留完整的识别结果，异常结束时<span class="change-delete">也</span>不要清空。${btn('replace-detail','周五前先看原型',{cls:'change-replace replacement-button',label:'查看替换前后：周五前先看原型',extra:`aria-expanded="${!!s.replacementOpen}"`})}<span class="change-tag">替换</span>，确认后再实施。<span class="change-add">这轮先保留本地版本。</span><span class="change-tag">新增</span>${s.replacementOpen?'<span class="old-word">替换前：<em>请在周五之前给我看一版原型</em><br>替换后：<em>周五前先看原型</em></span>':''}`;return `${btn('replace-detail',esc(s.text),{cls:'change-replace replacement-button',label:'查看整段文字版本对照',extra:`aria-expanded="${!!s.replacementOpen}"`})}${s.replacementOpen?`<span class="old-word">本次为整段改写 · 修改前：<em>${esc(s.history.at(-2)||SOURCE)}</em></span>`:''}`;}
function renderDocument(s){if(s.editing)return `<div class="editor-wrap"><textarea class="editor" aria-label="编辑完整正文" aria-describedby="edit-help-${s.id}" spellcheck="false">${esc(s.draft??s.text)}</textarea></div><div class="editor-info" id="edit-help-${s.id}"><span>草稿已保存 · 完成后应用</span><span data-char-count>${[...(s.draft??s.text)].length} 字</span></div>`;
 let html=!validText(s)?'<span class="empty-result">没有恢复到可用的文字。</span>':asrContext(s)&&s.mode==='compare'?asrBody(s):voiceContext(s)&&s.mode==='changes'&&s.history.length>1?revisionMarkup(s):esc(s.text);
 return `<div class="body-text" aria-label="当前有效正文">${html}</div>${asrContext(s)&&s.mode==='compare'?`<div class="asr-legend"><span><span class="${s.checked.every(Boolean)?'key-done':'key-waiting'}">${s.checked.every(Boolean)?'已确认':'待确认'}</span> 点按高亮词查看来源</span><span class="nav-diff">${btn('prev-diff','上一处',{cls:''})}${btn('next-diff','下一处',{cls:''})}</span></div>${candidate(s)}`:''}${voiceContext(s)&&s.mode==='changes'?'<div class="change-legend"><span class="change-add">新增 · 下划线</span><span class="change-delete">删除 · 删除线</span><span class="change-replace">替换 · 前后对照</span></div>':''}${s.draft!==null&&s.draft!==s.text&&!s.editing?`<div class="draft-resume"><span>有尚未应用的编辑草稿</span>${btn('edit','继续编辑',{cls:''})}</div>`:''}`;}
function renderCard(s,t){const spec=specs[s.id],busy=s.id==='error'&&s.recovery!=='done'||s.voicePhase!=='ready',empty=!validText(s),editing=s.editing;
 const heading=editing?'编辑正文':s.voicePhase==='recording'?'说说想怎么修改':s.voicePhase==='processing'?'正在生成新版':s.revisionFailed?'这次修改未完成':s.id==='error'?(s.recovery==='done'?'录音已中断':'正在保留识别结果'):s.manual?'检查后输入':voiceContext(s)&&s.history.length>1?'按你的要求改好了':asrContext(s)?'检查识别结果':'检查后输入';
 const compact=!editing&&!busy&&s.id!=='error'&&!s.revisionFailed;
 const status=editing?'<span class="status draft-status">编辑草稿</span>':s.voicePhase!=='ready'?'<span class="status">修改中</span>':s.id==='error'?'<span class="status warning-status">可能不完整</span>':s.revisionFailed?`<span class="status warning-status">V${s.history.length} · 已保留</span>`:s.manual?'<span class="status">已手动编辑</span>':voiceContext(s)?`<span class="status">V${s.history.length} · ${s.history.length>1?'已修改':'修改前'}</span>`:s.manual?'<span class="status">已手动编辑</span>':asrContext(s)?`<span class="status ${s.checked.every(Boolean)?'success':'warning-status'}">${s.checked.every(Boolean)?'2 处已检查':s.checked.filter(v=>!v).length+' 处待检查'}</span>`:'<span class="status success">识别完成</span>';
 const sub=editing?'只修改这一轮正文；不会向目标窗口输入。':s.voicePhase==='recording'?'原正文保留在下方，修改要求单独处理。':s.voicePhase==='processing'?'新版就绪前，原正文与编辑草稿保持不变。':s.revisionFailed?'已保留上一版正文，可以重试或继续检查。':s.manual?'手动修改已保留，尚未输入。':asrContext(s)?'比较实时与精修识别，采用你确认的一项。':voiceContext(s)?(s.history.length>1?'这是文字修改后的版本，尚未输入。':'已回到修改前的正文，尚未输入。'):s.id==='error'?'已停止采集，尽可能完成有效音频的识别。':'确认前可以检查、编辑，或继续口述修改。';
 let tools='';if(!editing&&asrContext(s))tools=`<div class="view-switch" aria-label="识别查看方式">${btn('reading','阅读',{cls:'',extra:`aria-pressed="${s.mode==='read'}"`})}${btn('comparing','校对 2',{cls:'',extra:`aria-pressed="${s.mode==='compare'}"`})}</div><span class="source-note">来自两次音频识别</span>`;
 else if(!editing&&voiceContext(s)&&s.voicePhase==='ready')tools=`<div class="view-switch" aria-label="文字修改查看方式">${btn('reading','阅读',{cls:'',extra:`aria-pressed="${s.mode==='read'}"`})}${btn('changes','查看修改',{cls:'',disabled:s.history.length<2||s.manual,extra:`aria-pressed="${s.mode==='changes'}"`})}</div>${btn('undo',`${icon('undo')}撤销本次`,{cls:'history-button',disabled:s.history.length<2||s.manual,tip:s.manual?'手动编辑后不能用旧的语音撤销覆盖正文':'撤销这一次语音修改'})}`;
 let alert='';if(s.id==='error'){let message=s.errorKind==='finish'?'收尾识别未完成，已保留最后可用预览。':s.errorKind==='backlog'?'音频处理积压，部分声音可能未被记录。':s.errorKind==='no-preview'?'收尾识别失败，这个后端没有可用预览。':'麦克风连接中断，已保留可识别的内容。';if(s.recovery==='stopped')message='采集已停止，接着处理队列中的有效音频。';if(s.recovery==='finishing')message='正在完成已收到音频的识别，预览仍然保留。';alert=`<aside class="alert">${icon('warning')}<div><strong>${message}</strong><p>${empty?'没有文字可回退，请重新录音。':'无法定位到具体文字，请检查整段内容。'}本次不会自动输入。</p></div></aside>`;}
 let instruction='';if(s.voicePhase!=='ready')instruction=`<div class="instruction"><div class="label">本轮修改要求 · 演示口述</div><p>${s.history.length<2?s.instruction:'再缩短一点，保留“不自动输入”的提醒。'}</p></div><div class="voice-progress">${s.voicePhase==='recording'?`${icon('mic')}正在听修改要求`:`${icon('loader')}正在修改 · 原文不会被空结果覆盖`}</div>`;
 let actions=editing?`${btn('pause','暂不应用',{ic:'undo'})}<span class="spacer"></span>${btn('save','完成编辑',{cls:'action primary',ic:'check',disabled:!s.draft?.trim()})}`:s.voicePhase==='recording'?`${btn('cancel-voice','取消修改',{ic:'close'})}<span class="spacer"></span>${btn('end-voice','结束口述',{cls:'action primary',ic:'check'})}`:s.voicePhase==='processing'?`${btn('cancel-voice','取消修改',{ic:'close'})}<span class="spacer"></span>${btn('waiting','正在修改',{cls:'action primary loading',ic:'loader',disabled:true})}`:`${btn('copy','',{cls:'action icon-only',ic:'copy',disabled:empty||busy,label:'复制正文',tip:'复制纯正文'})}${btn('edit','编辑',{cls:'action secondary',ic:'edit',disabled:empty||busy})}${btn('voice',`语音修改 <kbd>F9</kbd>`,{ic:'mic',disabled:empty||busy,tip:'修改当前正文；原型请点击按钮，未连接系统F9'})}<span class="spacer"></span>${btn('insert','确认输入',{cls:'action primary',ic:'insert',disabled:empty||busy||!s.target})}`;
 if(compact){actions=`${btn('copy','',{cls:'action icon-only',ic:'copy',disabled:empty,label:'复制正文',tip:'复制纯正文'})}${btn('edit','',{cls:'action icon-only',ic:'edit',disabled:empty,label:'编辑正文',tip:'编辑整段正文'})}${btn('voice','<kbd>F9</kbd>',{cls:'action voice-compact',ic:'mic',disabled:empty,label:'语音修改 F9',tip:'语音修改（F9）；原型请点击'})}<span class="spacer"></span>${btn('insert','确认输入',{cls:'action primary',ic:'insert',disabled:empty||!s.target})}`;}
 const controls=s.id==='error'&&s.voicePhase!=='processing'?`<select aria-label="异常演示场景"><option value="device" ${s.errorKind==='device'?'selected':''}>设备中断 · 尽力收尾</option><option value="backlog" ${s.errorKind==='backlog'?'selected':''}>积压 · 处理有效音频</option><option value="finish" ${s.errorKind==='finish'?'selected':''}>收尾失败 · 回退预览</option><option value="no-preview" ${s.errorKind==='no-preview'?'selected':''}>无预览 · 收尾也失败</option></select>${btn('recover',s.recovery==='done'?'演示收尾过程':'继续下一步',{cls:''})}`:s.voicePhase==='processing'?`${btn('voice-fail','模拟修改失败',{cls:''})}${btn('voice-result','显示演示新版',{cls:''})}`:`<span>${s.id==='voice'?'点击语音修改可演示下一轮；未连接麦克风。':'演示开关不属于产品浮层。'}</span>${btn('target',s.target?'模拟目标变化':'恢复原目标',{cls:''})}`;
 return `<section class="scheme ${t}" data-card="${s.id}" data-scheme="${t}">${sheet?`<p class="sheet-label">${Object.keys(specs).indexOf(s.id)+1}. ${spec.name}</p>`:''}<div class="scheme-title"><h2>${t==='indigo'?'A · 雾白靛蓝':'B · 暖纸松绿'}</h2><div class="theme-description"><p>${t==='indigo'?'清晰、轻快的工具感':'温暖、舒展的批注感'}</p><span class="swatches" aria-hidden="true"><span></span><span></span><span></span></span></div></div><article class="voice-panel ${compact?'compact':''}" aria-label="${t==='indigo'?'雾白靛蓝':'暖纸松绿'} · ${spec.name}">${s.closed?`<div class="closed">浮层已收起，正文和草稿仍保留。<br>${btn('reopen','重新打开',{cls:'action secondary'})}</div>`:`<header class="panel-top"><span class="app-mark">${icon('mic')}</span><div class="identity"><span class="brand">HyprVoice</span>${compact?'':'<span class="session-note">本次识别</span>'}</div>${compact?status:''}${btn('close','',{cls:'icon-button',ic:'close',label:'收起浮层',tip:'收起浮层并保留草稿'})}</header>${compact?'':`<div class="panel-heading"><h3>${heading}</h3>${status}</div><p class="subline">${sub}</p>`}${tools?`<div class="document-tools">${tools}</div>`:''}<div class="document">${renderDocument(s)}${instruction}</div>${alert}<div class="target-line"><span>${s.target?'输入到 <strong>文本编辑器 · 迭代笔记</strong>':'目标窗口已变化，请回到原窗口'}</span>${btn('target-info',s.targetOpen?'收起检查':'核对目标',{cls:'',ic:'expand',tip:'查看目标窗口检查信息',extra:`aria-expanded="${s.targetOpen}"`})}</div>${s.targetOpen?`<p class="subline">${s.target?'目标仍绑定录音开始时的窗口，浮层获焦不改变目的地。':'目的地未被改为新窗口。正文保留，当前禁止输入。'}</p>`:''}<div class="panel-actions">${actions}</div>${s.notice?`<p class="inline-notice ${s.noticeKind||''}" role="status">${esc(s.notice)}</p>`:''}`}</article><div class="demo-controls">${controls}</div><p class="scheme-description">${voiceContext(s)?'文字版本与识别候选分开保存':spec.subtitle}。${voiceContext(s)?'查看修改只比较文字版本，不冒充音频候选。':s.id==='asr'?'琥珀点线是“待确认”，选择后的实线表示已采用；不是置信度。':s.id==='voice'?'查看修改只比较文字版本，不冒充音频候选。':s.id==='edit'?'草稿与当前正文分开；暂不应用或刷新也能继续编辑。':s.id==='error'?'没有时间对齐依据时，异常提示只作用于整体。':'复制、编辑用熟悉图标，语音修改保留F9提示，确认输入独立突出。'}</p></section>`;
}
function positionCandidates(){ /* Candidate shelf follows its highlighted paragraph in normal flow. */ }
function render(){const focused=document.activeElement;const fc=focused?.closest?.('[data-card]');const oldFocus=fc&&focused.dataset.action?{card:fc.dataset.card,scheme:fc.dataset.scheme,action:focused.dataset.action,diff:focused.dataset.diff}:null;document.querySelectorAll('[data-theme]').forEach(e=>e.setAttribute('aria-pressed',e.dataset.theme===theme));document.querySelectorAll('[data-state]').forEach(e=>{if(e.dataset.state===active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});const themes=theme==='compare'?['indigo','sage']:[theme];document.querySelector('#stage').className=sheet?'sheet':theme==='compare'?'pair':'focus';document.querySelector('#stage').innerHTML=sheet?Object.values(states).map(s=>renderCard(s,themes[0])).join(''):themes.map(t=>renderCard(states[active],t)).join('');positionCandidates();if(oldFocus){const scope=document.querySelector(`[data-card="${oldFocus.card}"][data-scheme="${oldFocus.scheme}"]`);const focusTarget=scope?.querySelector(`[data-action="${oldFocus.action}"]${oldFocus.diff!==undefined?`[data-diff="${oldFocus.diff}"]`:''}`);if(focusTarget&&!focusTarget.disabled)focusTarget.focus({preventScroll:true});else{const redirects={edit:'textarea',save:'[data-action=edit]',pause:'[data-action=edit]',voice:'[data-action=end-voice]',"end-voice":'[data-action=cancel-voice]',"cancel-voice":'[data-action=voice]',"voice-fail":'[data-action=voice]',"voice-result":'[data-action=voice]',undo:'[data-action=reading]',choose:'.asr-mark',"accept-current":'.asr-mark',close:'[data-action=reopen]',reopen:'[data-action=close]'};const next=scope?.querySelector(redirects[oldFocus.action]||'[data-action=insert]');next?.focus({preventScroll:true});}}}
document.querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>{theme=b.dataset.theme;params.set('theme',theme);history.replaceState(null,'','?'+params);render();}));
document.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.state;params.set('state',active);history.replaceState(null,'','?'+params);render();}));
document.querySelector('#stage').addEventListener('input',e=>{if(!e.target.matches('textarea'))return;const s=states[e.target.closest('[data-card]').dataset.card];s.draft=e.target.value;persist();document.querySelectorAll(`[data-card="${s.id}"] textarea`).forEach(el=>{if(el!==e.target)el.value=s.draft;});document.querySelectorAll(`[data-card="${s.id}"]`).forEach(card=>{card.querySelector('[data-char-count]').textContent=[...s.draft].length+' 字';card.querySelector('[data-action="save"]').disabled=!s.draft.trim();});});
document.querySelector('#stage').addEventListener('change',e=>{if(!e.target.matches('select'))return;const s=states.error;s.errorKind=e.target.value;s.recovery='done';s.text=s.errorKind==='no-preview'?'':s.errorKind==='finish'?LAST_PREVIEW:RECOVERED;s.notice='';s.draft=null;s.manual=false;persist();render();});
document.querySelector('#stage').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const card=b.closest('[data-card]');const s=states[card.dataset.card];const a=b.dataset.action;s.notice='';s.noticeKind='';
 if(a==='replace-detail')s.replacementOpen=!s.replacementOpen;
 if(a==='open-diff'){s.openDiff=+b.dataset.diff;s.mode='compare';}if(a==='close-diff')s.openDiff=-1;
 if(a==='accept-current'){s.checked[s.openDiff]=true;s.openDiff=-1;s.notice='已确认保留当前词，正文不变。';}
 if(a==='choose'){const n=s.openDiff;s.selected[n]=1-s.selected[n];s.checked[n]=true;s.text=sourceText(s);s.revision++;s.openDiff=-1;s.notice='已采用备选，正文和复制内容同步更新。';}
 if(a==='prev-diff'||a==='next-diff'){s.openDiff=s.openDiff<0?Math.max(0,s.checked.findIndex(v=>!v)):(s.openDiff+(a==='next-diff'?1:-1)+2)%2;s.mode='compare';}
 if(a==='reading'){s.mode='read';s.openDiff=-1;}if(a==='comparing'){s.mode='compare';s.openDiff=0;}if(a==='changes'){s.mode='changes';s.openDiff=-1;}
 if(a==='edit'){s.editing=true;s.draft=s.draft??s.text;s.draftBase=s.revision;s.openDiff=-1;}
 if(a==='pause'){s.editing=false;s.notice='尚未应用修改；草稿保留，可继续编辑。';}
 if(a==='save'&&s.draft?.trim()){if(s.draftBase!==s.revision)s.notice='正文已更新，草稿仍保留。请先核对新版，避免覆盖。';else{s.text=s.draft;s.manual=true;s.revisionFailed=false;s.editing=false;s.revision++;s.mode='read';s.openDiff=-1;s.notice='编辑已应用。请检查后确认输入。';}}
 if(a==='voice'){if(s.draft!==null&&s.draft!==s.text){s.notice='请先完成或处理编辑草稿，再修改当前正文。';}else{s.voicePhase='recording';s.revisionFailed=false;s.voiceBase=s.text;s.voiceRevision=s.revision;s.openDiff=-1;s.mode='read';}}
 if(a==='end-voice')s.voicePhase='processing';
 if(a==='cancel-voice'){s.voicePhase='ready';s.notice='已取消本次语音修改，正文保持原样。';s.voiceRevision=null;}
 if(a==='voice-fail'){s.revisionFailed=true;s.noticeKind='error';s.voicePhase='ready';s.notice='这次修改未完成，已保留修改前的正文。';s.voiceRevision=null;}
 if(a==='voice-result'){if(s.voiceRevision!==s.revision){s.notice='旧版修改结果已忽略，当前正文没有被覆盖。';s.voicePhase='ready';}else{if(!voiceContext(s))s.history=[s.voiceBase];else if(s.history.at(-1)!==s.voiceBase)s.history.push(s.voiceBase);s.revised=true;s.revisionFailed=false;s.text=s.history.length===1?VOICE2:VOICE3;s.history.push(s.text);s.revision++;s.voicePhase='ready';s.mode='read';s.manual=false;s.draft=null;s.notice='新版已保留，等待你确认输入。';}}
 if(a==='undo'&&s.history.length>1){s.revisionFailed=false;s.history.pop();s.text=s.history.at(-1);s.revision++;s.mode='read';s.notice='已撤销本次语音修改。';s.draft=null;}
 if(a==='target-info')s.targetOpen=!s.targetOpen;if(a==='target'){s.target=!s.target;s.notice=s.target?'已恢复原目标，仍需确认后输入。':'目标已变化，输入已暂停，正文仍保留。';}
 if(a==='close')s.closed=true;if(a==='reopen')s.closed=false;
 if(a==='recover'){s.recovery=s.recovery==='done'?'stopped':s.recovery==='stopped'?'finishing':'done';s.text=s.errorKind==='no-preview'?'':s.recovery==='done'&&s.errorKind!=='finish'?RECOVERED:LAST_PREVIEW;}
 if(a==='copy'||a==='insert'){document.querySelector('#output-text').textContent=s.text;document.querySelector('#output-status').textContent=a==='copy'?'复制内容 · 只有当前正文':'确认输入演示 · 只有当前正文';if(a==='copy'){try{await navigator.clipboard.writeText(s.text);s.notice='已复制当前正文。';}catch{s.noticeKind='error';s.notice='浏览器未允许复制。正文保留在下方，可手动复制。';}}else{s.notice='待输入正文已展示在下方；原型未向真实窗口输入。';}}
 persist();render();
});
document.querySelector('#reset').addEventListener('click',()=>{try{localStorage.removeItem(STORAGE);}catch{}location.reload();});
document.querySelector('#stage').addEventListener('keydown',e=>{if(e.key!=='Escape')return;const card=e.target.closest('[data-card]');if(!card)return;const s=states[card.dataset.card];if(s.openDiff>=0){e.preventDefault();s.openDiff=-1;render();}});
